settings.custom_liquid:
{% comment %}
  ============================================================
  EVIOLA PRODUCT INFO
  Quantity + Like + Quick Chat
  ============================================================
{% endcomment %}


<div
  class="eviola-product-info"
  style="
    --eviola-top-padding: 10px;
    --eviola-bottom-padding: 0px;
  "
>

  <!-- ========================================================
       QUANTITY + LIKE + QUICK CHAT
       ======================================================== -->

  <div class="quick-chat-root">

    <div class="action-row">

      <!-- Quantity Picker -->

      <div
        class="qty-picker"
        data-qty-picker
      >

        <button
          type="button"
          data-qty-minus
          aria-label="Decrease quantity"
        >
          −
        </button>

        <span data-qty-value>1</span>

        <button
          type="button"
          data-qty-plus
          aria-label="Increase quantity"
        >
          +
        </button>

      </div>


      <!-- Like / Wishlist -->

      <button
        type="button"
        class="wishlist-btn"
        data-wishlist
        aria-label="Add to wishlist"
        aria-pressed="false"
      >

        <svg
          viewBox="0 0 24 24"
          fill="none"
          stroke="#444"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        >

          <path
            d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"
          />

        </svg>

      </button>


      <!-- Quick Chat -->

      <button
        type="button"
        class="chat-btn"
        data-open-chat
      >

        <svg
          viewBox="0 0 24 24"
          fill="none"
          stroke="white"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        >

          <path
            d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"
          />

          <path d="M8 10h8" />

          <path d="M8 14h5" />

        </svg>

        <span>Quick Chat</span>

      </button>

    </div>


    <!-- ======================================================
         CHAT WINDOW
         ====================================================== -->

    <div
      class="chat-window"
      data-chat-window
    >

      <div class="chat-header">

        <strong>Eviola Support</strong>

        <button
          type="button"
          class="close-btn"
          aria-label="Close chat"
          data-close-chat
        >

          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          >

            <line
              x1="18"
              y1="6"
              x2="6"
              y2="18"
            />

            <line
              x1="6"
              y1="6"
              x2="18"
              y2="18"
            />

          </svg>

        </button>

      </div>


      <div
        class="messages"
        data-messages
      >

        <div class="intro-text">

          Hello from Eviola! Need help, tips, or just curious?
          We&apos;re always here to chat! ♥️

          <br>

          You might be wondering

        </div>


        <div class="quick-options">

          <button
            type="button"
            data-option="📦 Where is my order?"
          >
            📦 Where is my order?
          </button>

          <button
            type="button"
            data-option="📍 How to track my order?"
          >
            📍 How to track my order?
          </button>

          <button
            type="button"
            data-option="↩ Returns & Refunds"
          >
            ↩ Returns & Refunds
          </button>

          <button
            type="button"
            data-option="🚚 Delivery Information"
          >
            🚚 Delivery Information
          </button>

          <button
            type="button"
            data-option="🎁 Product Questions"
          >
            🎁 Product Questions
          </button>

          <button
            type="button"
            data-option="💳 Payment Help"
          >
            💳 Payment Help
          </button>

          <button
            type="button"
            data-option="👩 Talk to our team"
          >
            👩 Talk to our team
          </button>

        </div>

      </div>


      <!-- Typing indicator -->

      <div
        class="typing"
        data-typing
        style="display:none;"
      >
        Eviola is typing...
      </div>


      <!-- Chat input -->

      <div class="chat-input">

        <input
          type="text"
          placeholder="Type your message..."
          data-chat-input
        >


        <!-- File upload -->

        <div class="upload-wrap">

          <label
            class="upload-label"
            for="eviola-upload-image"
          >

            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            >

              <path
                d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"
              />

            </svg>

          </label>

          <input
            id="eviola-upload-image"
            type="file"
            accept="image/*"
            data-file-input
          >

          <span
            class="file-name"
            data-file-name
          ></span>

        </div>


        <button
          type="button"
          id="sendMessage"
          data-send-message
        >
          Send
        </button>

      </div>

    </div>

  </div>

</div>


<style>

/* ============================================================
   MAIN ROOT
   ============================================================ */

.eviola-product-info {

  width: 100%;

  /*
   * CHANGE THESE TWO VALUES
   *
   * Top padding:
   * 0px = no top padding
   * 10px = small
   * 20px = medium
   * 30px = large
   */

  padding-top: var(--eviola-top-padding);

  /*
   * Bottom padding:
   * 0px = no bottom padding
   * 10px = small
   * 20px = medium
   * 30px = large
   */

  padding-bottom: var(--eviola-bottom-padding);

}


/* ============================================================
   QUICK CHAT / ACTION ROW
   ============================================================ */

.quick-chat-root .action-row {

  display: flex;

  gap: 8px;

}


/* ============================================================
   QUANTITY PICKER
   ============================================================ */

.quick-chat-root .qty-picker {

  flex: 4;

  height: 48px;

  border: 1px solid #000;

  display: flex;

  justify-content: space-between;

  align-items: center;

  background: #fff;

}


.quick-chat-root .qty-picker button {

  width: 42px;

  height: 100%;

  border: none;

  background: #fff;

  font-size: 22px;

  cursor: pointer;

}


.quick-chat-root .qty-picker span {

  font-size: 16px;

}


/* ============================================================
   LIKE / WISHLIST
   ============================================================ */

.quick-chat-root .wishlist-btn {

  flex: 1;

  min-width: 48px;

  height: 48px;

  border: 1px solid #000;

  background: #fff;

  padding: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

}


.quick-chat-root .wishlist-btn svg {

  width: 20px;

  height: 20px;

}


/* ============================================================
   QUICK CHAT BUTTON
   ============================================================ */

.quick-chat-root .chat-btn {

  flex: 4.5;

  height: 48px;

  border: none;

  background: #f9758d;

  color: #fff;

  font-weight: 600;

  gap: 8px;

  padding: 0 12px;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

}


.quick-chat-root .chat-btn svg {

  width: 19px;

  height: 19px;

  flex-shrink: 0;

}


.quick-chat-root .chat-btn span {

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;

}


/* ============================================================
   CHAT WINDOW
   ============================================================ */

.quick-chat-root .chat-window {

  position: fixed;

  right: 18px;

  bottom: 80px;

  width: 360px;

  height: 620px;

  background: #fff;

  border-radius: 20px;

  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.18);

  display: flex;

  flex-direction: column;

  overflow: hidden;

  z-index: 9999;

  opacity: 0;

  transform:
    translateY(24px)
    scale(0.96);

  pointer-events: none;

  visibility: hidden;

  transition:
    opacity 0.28s ease,
    transform 0.28s
      cubic-bezier(0.34, 1.56, 0.64, 1),
    visibility 0s linear 0.28s;

}


.quick-chat-root .chat-window.show {

  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  pointer-events: auto;

  visibility: visible;

  transition:
    opacity 0.28s ease,
    transform 0.28s
      cubic-bezier(0.34, 1.56, 0.64, 1),
    visibility 0s linear 0s;

}


/* ============================================================
   MOBILE CHAT
   ============================================================ */

@media (max-width: 480px) {

  .quick-chat-root .chat-window {

    right: 10px;

    left: 10px;

    bottom: 76px;

    width: auto;

    height: min(620px, 78vh);

  }

  .quick-chat-root .chat-btn {

    font-size: 14px;

  }

}


/* ============================================================
   CHAT HEADER
   ============================================================ */

.quick-chat-root .chat-header {

  background: #f9758d;

  color: #fff;

  padding:
    16px
    16px
    16px
    20px;

  display: flex;

  justify-content: space-between;

  align-items: center;

}


.quick-chat-root .chat-header strong {

  font-size: 16px;

  letter-spacing: 0.2px;

}


/* ============================================================
   CLOSE BUTTON
   ============================================================ */

.quick-chat-root .close-btn {

  width: 30px;

  height: 30px;

  border: none;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.16);

  color: #fff;

  display: flex;

  align-items: center;

  justify-content: center;

  cursor: pointer;

  transition:
    background 0.18s ease,
    transform 0.18s ease;

}


.quick-chat-root .close-btn svg {

  width: 14px;

  height: 14px;

}


.quick-chat-root .close-btn:hover {

  background:
    rgba(255, 255, 255, 0.3);

}


.quick-chat-root .close-btn:active {

  transform: scale(0.9);

}


/* ============================================================
   MESSAGES
   ============================================================ */

.quick-chat-root .messages {

  flex: 1;

  padding: 16px;

  overflow: auto;

  background: #fafafa;

}


.quick-chat-root .intro-text {

  font-size: 14px;

  line-height: 1.5;

  color: #333;

  margin-bottom: 14px;

}


/* ============================================================
   MESSAGES
   ============================================================ */

.quick-chat-root .bot-message,
.quick-chat-root .user-message {

  padding: 12px 14px;

  border-radius: 14px;

  margin-bottom: 10px;

  max-width: 85%;

  line-height: 1.4;

  font-size: 14px;

}


.quick-chat-root .bot-message {

  background: #fff;

  box-shadow:
    0 1px 2px
    rgba(0, 0, 0, 0.06);

}


.quick-chat-root .user-message {

  background: #f9758d;

  color: #fff;

  margin-left: auto;

}


/* ============================================================
   QUICK OPTIONS
   ============================================================ */

.quick-chat-root .quick-options button {

  display: block;

  width: 100%;

  margin: 8px 0;

  padding: 12px;

  border: 1px solid #eee;

  background: #fff;

  border-radius: 12px;

  text-align: left;

  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;

}


.quick-chat-root .quick-options button:hover {

  background: #fff5f6;

  border-color: #f9758d;

}


/* ============================================================
   TYPING
   ============================================================ */

.quick-chat-root .typing {

  padding: 10px 16px;

  font-size: 13px;

  color: #777;

}


/* ============================================================
   CHAT INPUT
   ============================================================ */

.quick-chat-root .chat-input {

  display: flex;

  align-items: center;

  gap: 8px;

  padding: 12px;

  border-top: 1px solid #eee;

  background: #fff;

}


.quick-chat-root
.chat-input
input[type="text"] {

  flex: 1;

  padding: 10px 12px;

  border: 1px solid #ddd;

  border-radius: 10px;

  font-size: 14px;

  outline: none;

  transition:
    border-color 0.15s ease;

}


.quick-chat-root
.chat-input
input[type="text"]:focus {

  border-color: #f9758d;

}


/* ============================================================
   FILE UPLOAD
   ============================================================ */

.quick-chat-root .upload-wrap {

  position: relative;

  flex-shrink: 0;

}


.quick-chat-root
.upload-wrap
input[type="file"] {

  position: absolute;

  inset: 0;

  width: 36px;

  height: 36px;

  opacity: 0;

  cursor: pointer;

}


.quick-chat-root .upload-label {

  width: 36px;

  height: 36px;

  border-radius: 10px;

  border: 1px solid #ddd;

  background: #fff;

  display: flex;

  align-items: center;

  justify-content: center;

  color: #888;

  cursor: pointer;

  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    color 0.15s ease;

}


.quick-chat-root .upload-label svg {

  width: 18px;

  height: 18px;

}


.quick-chat-root
.upload-wrap:hover
.upload-label {

  border-color: #f9758d;

  color: #f9758d;

  background: #fff5f6;

}


.quick-chat-root
.upload-wrap.has-file
.upload-label {

  border-color: #f9758d;

  color: #f9758d;

  background: #fff5f6;

}


.quick-chat-root .file-name {

  position: absolute;

  bottom: -20px;

  left: 0;

  font-size: 11px;

  color: #f9758d;

  white-space: nowrap;

  max-width: 120px;

  overflow: hidden;

  text-overflow: ellipsis;

}


/* ============================================================
   SEND
   ============================================================ */

.quick-chat-root
.chat-input
button#sendMessage {

  border: none;

  background: #f9758d;

  color: #fff;

  font-weight: 600;

  padding: 0 16px;

  height: 36px;

  border-radius: 10px;

  cursor: pointer;

  transition:
    background 0.15s ease;

}


.quick-chat-root
.chat-input
button#sendMessage:hover {

  background: #f45f7a;

}


/* ============================================================
   WHATSAPP
   ============================================================ */

.quick-chat-root .wa-link {

  display: inline-flex;

  align-items: center;

  gap: 8px;

  background: #25d366;

  color: #fff;

  padding: 10px 16px;

  border-radius: 10px;

  text-decoration: none;

  font-weight: 600;

  font-size: 14px;

  margin-top: 4px;

}


.quick-chat-root .wa-link svg {

  width: 18px;

  height: 18px;

  flex-shrink: 0;

}

</style>


<script>

(function() {


  /* ==========================================================
     ROOT
     ========================================================== */

  const root =
    document.querySelector(
      '.eviola-product-info'
    );


  if (!root) return;


  /* ==========================================================
     QUICK CHAT
     ========================================================== */

  const chatWindow =
    root.querySelector(
      '[data-chat-window]'
    );

  const openChat =
    root.querySelector(
      '[data-open-chat]'
    );

  const closeChat =
    root.querySelector(
      '[data-close-chat]'
    );

  const messages =
    root.querySelector(
      '[data-messages]'
    );

  const typing =
    root.querySelector(
      '[data-typing]'
    );

  const input =
    root.querySelector(
      '[data-chat-input]'
    );

  const sendButton =
    root.querySelector(
      '[data-send-message]'
    );


  /* ==========================================================
     OPEN CHAT
     ========================================================== */

  if (openChat) {

    openChat.addEventListener(
      'click',
      function() {

        chatWindow.classList.add(
          'show'
        );

      }
    );

  }


  /* ==========================================================
     CLOSE CHAT
     ========================================================== */

  if (closeChat) {

    closeChat.addEventListener(
      'click',
      function() {

        chatWindow.classList.remove(
          'show'
        );

      }
    );

  }


  /* ==========================================================
     SCROLL MESSAGES
     ========================================================== */

  function scrollMessages() {

    if (messages) {

      messages.scrollTop =
        messages.scrollHeight;

    }

  }


  /* ==========================================================
     USER MESSAGE
     ========================================================== */

  function addUserMessage(text) {

    const div =
      document.createElement(
        'div'
      );

    div.className =
      'user-message';

    div.textContent =
      text;

    messages.appendChild(
      div
    );

    scrollMessages();

  }


  /* ==========================================================
     BOT MESSAGE
     ========================================================== */

  function addBotMessage(text) {

    const div =
      document.createElement(
        'div'
      );

    div.className =
      'bot-message';

    div.textContent =
      text;

    messages.appendChild(
      div
    );

    scrollMessages();

  }


  /* ==========================================================
     WHATSAPP
     ========================================================== */

  function addWhatsAppMessage() {

    const div =
      document.createElement(
        'div'
      );

    div.className =
      'bot-message';

    div.innerHTML = `

      Our team is ready to help you!

      <br>

      <a
        href="https://wa.me/917780022167"
        target="_blank"
        rel="noopener noreferrer"
        class="wa-link"
      >

        <svg
          viewBox="0 0 24 24"
          fill="currentColor"
          xmlns="http://www.w3.org/2000/svg"
        >

          <path
            d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.198.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"
          />

        </svg>

        Chat on WhatsApp

      </a>

    `;

    messages.appendChild(
      div
    );

    scrollMessages();

  }


  /* ==========================================================
     CHAT RESPONSES
     ========================================================== */

  const responses = {

    '📦 Where is my order?':
      "Please enter your Order ID and we'll look it up for you.",

    '📍 How to track my order?':
      'You can track your order anytime via My Orders in the menu. You should also have received a confirmation email with a tracking link.',

    '↩ Returns & Refunds':
      'Returns are accepted within 7 days of delivery. Please reach out with your order details.',

    '🚚 Delivery Information':
      'Delivery usually takes 3–7 business days across India.',

    '🎁 Product Questions':
      "Ask us anything about our artificial jewelry — we're happy to help!",

    '💳 Payment Help':
      'We accept UPI, Credit/Debit Cards, and Cash on Delivery (COD).',

    '👩 Talk to our team':
      'WHATSAPP'

  };


  /* ==========================================================
     QUICK OPTIONS
     ========================================================== */

  root
    .querySelectorAll('[data-option]')
    .forEach(function(button) {

      button.addEventListener(
        'click',
        function() {

          const option =
            button.getAttribute(
              'data-option'
            );

          addUserMessage(
            option
          );

          typing.style.display =
            'block';

          scrollMessages();


          setTimeout(
            function() {

              typing.style.display =
                'none';


              if (
                responses[option] ===
                'WHATSAPP'
              ) {

                addWhatsAppMessage();

              }
              else {

                addBotMessage(
                  responses[option]
                );

              }

            },
            800
          );

        }
      );

    });


  /* ==========================================================
     SEND MESSAGE
     ========================================================== */

  function handleSend() {

    const text =
      input.value.trim();

    if (!text) return;


    addUserMessage(
      text
    );

    input.value = '';

    typing.style.display =
      'block';

    scrollMessages();


    setTimeout(
      function() {

        typing.style.display =
          'none';

        addBotMessage(
          'Thanks! Our team will get back to you shortly.'
        );

      },
      800
    );

  }


  if (sendButton) {

    sendButton.addEventListener(
      'click',
      handleSend
    );

  }


  if (input) {

    input.addEventListener(
      'keydown',
      function(event) {

        if (
          event.key === 'Enter'
        ) {

          handleSend();

        }

      }
    );

  }


  /* ==========================================================
     FILE UPLOAD
     ========================================================== */

  const fileInput =
    root.querySelector(
      '[data-file-input]'
    );

  const fileName =
    root.querySelector(
      '[data-file-name]'
    );

  const uploadWrap =
    root.querySelector(
      '.upload-wrap'
    );


  if (fileInput) {

    fileInput.addEventListener(
      'change',
      function() {

        if (
          fileInput.files &&
          fileInput.files.length
        ) {

          fileName.textContent =
            fileInput.files[0].name;

          uploadWrap.classList.add(
            'has-file'
          );

        }
        else {

          fileName.textContent =
            '';

          uploadWrap.classList.remove(
            'has-file'
          );

        }

      }
    );

  }


  /* ==========================================================
     WISHLIST / LIKE
     ========================================================== */

  const wishlist =
    root.querySelector(
      '[data-wishlist]'
    );


  if (wishlist) {

    wishlist.addEventListener(
      'click',
      function() {

        const active =
          wishlist.getAttribute(
            'aria-pressed'
          ) === 'true';


        wishlist.setAttribute(
          'aria-pressed',
          active
            ? 'false'
            : 'true'
        );


        const svg =
          wishlist.querySelector(
            'svg'
          );


        if (active) {

          svg.setAttribute(
            'fill',
            'none'
          );

          svg.setAttribute(
            'stroke',
            '#444'
          );

        }
        else {

          svg.setAttribute(
            'fill',
            '#f9758d'
          );

          svg.setAttribute(
            'stroke',
            '#f9758d'
          );

        }

      }
    );

  }


  /* ==========================================================
     QUANTITY PICKER
     ========================================================== */

  const qtyValue =
    root.querySelector(
      '[data-qty-value]'
    );

  const qtyMinus =
    root.querySelector(
      '[data-qty-minus]'
    );

  const qtyPlus =
    root.querySelector(
      '[data-qty-plus]'
    );


  let quantity = 1;


  function updateQuantity() {

    qtyValue.textContent =
      quantity;


    /*
     * Update Shopify's real quantity input.
     */

    const quantityInput =
      document.querySelector(
        'form[action*="/cart/add"] input[name="quantity"]'
      );


    if (quantityInput) {

      quantityInput.value =
        quantity;

      quantityInput.dispatchEvent(
        new Event(
          'change',
          {
            bubbles: true
          }
        )
      );

    }

  }


  if (qtyMinus) {

    qtyMinus.addEventListener(
      'click',
      function() {

        if (quantity > 1) {

          quantity--;

          updateQuantity();

        }

      }
    );

  }


  if (qtyPlus) {

    qtyPlus.addEventListener(
      'click',
      function() {

        quantity++;

        updateQuantity();

      }
    );

  }


})();

</script>

